public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 2, 2, 3, 5};
        int low = 0, high = a.length - 1, index = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (a[mid] == 2) {
                index = mid;
                high = mid - 1;
            } else if (a[mid] < 2) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        System.out.println(index);
    }
}
